// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testRegression_property() public {
        address caller = address(0x123);
        assertFalse(c.approvedToLog(caller));

        vm.prank(caller);
        bool result = c.logRegisteredPubkey(
            bytes32(uint256(0x1)),
            bytes32(uint256(0x2))
        );

        assertFalse(result);
    }
}
